window.initConversionAgents = function(root=document) {
  root.querySelectorAll('[data-home-agent-switcher]').forEach(switcher => {
    if (switcher.dataset.previewInitialized) return;
    switcher.dataset.previewInitialized = 'true';
    const tabs = [...switcher.querySelectorAll('[role="tab"]')];
    const panels = [...switcher.querySelectorAll('[role="tabpanel"]')];
    function activate(index, focus=false) {
      tabs.forEach((tab,i) => {
        const active=i===index;
        tab.setAttribute('aria-selected', String(active));
        tab.tabIndex=active?0:-1;
        tab.toggleAttribute('data-active',active);
        const description=tab.querySelector('[data-agent-description]');
        if (description) description.hidden=!active;
      });
      panels.forEach((panel,i) => {
        const active=i===index;
        panel.toggleAttribute('data-active',active);
        panel.setAttribute('aria-hidden',String(!active));
        panel.inert=!active;
      });
      if (focus) tabs[index].focus();
    }
    tabs.forEach((tab,index)=>{
      tab.addEventListener('click',()=>activate(index));
      tab.addEventListener('keydown',event=>{
        let next;
        if (event.key==='ArrowDown'||event.key==='ArrowRight') next=(index+1)%tabs.length;
        if (event.key==='ArrowUp'||event.key==='ArrowLeft') next=(index+tabs.length-1)%tabs.length;
        if (event.key==='Home') next=0;
        if (event.key==='End') next=tabs.length-1;
        if (next!==undefined){event.preventDefault();activate(next,true)}
      });
    });
    activate(0);
  });
};
